// FinishedAtNotNil applies the NotNil predicate on the "finished_at" field.
func FinishedAtNotNil() predicate.NocoDBRestore {
	return predicate.NocoDBRestore(sql.FieldNotNull(FieldFinishedAt))
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.NocoDBRestore) predicate.NocoDBRestore {
	return predicate.NocoDBRestore(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.NocoDBRestore) predicate.NocoDBRestore {
	return predicate.NocoDBRestore(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.NocoDBRestore) predicate.NocoDBRestore {
	return predicate.NocoDBRestore(sql.NotPredicates(p))
}
